from pathlib import Path

path = Path('src/components/studio/VideoTools.jsx')
text = path.read_text()

def replace_once(old, new, label):
    global text
    count = text.count(old)
    if count != 1:
        raise SystemExit(f'{label}: expected exactly 1 match, found {count}')
    text = text.replace(old, new, 1)

replace_once(
"import DynamicAiModelControls, { buildModelToolInput, getMappedModelField } from '@/components/studio/DynamicAiModelControls';",
"import { buildModelToolInput, getMappedModelField } from '@/components/studio/DynamicAiModelControls';",
'import')

replace_once(
"  shot_references: [],\n  transition_reference_id: '',",
"  shot_references: [],\n  shot_video_references: [],\n  transition_reference_id: '',",
'new shot video refs')

replace_once(
"        shot_references: Array.isArray(shot.shot_references) ? shot.shot_references : [],\n        transition_reference_id: shot.transition_reference_id || '',",
"        shot_references: Array.isArray(shot.shot_references) ? shot.shot_references : [],\n        shot_video_references: Array.isArray(shot.shot_video_references) ? shot.shot_video_references : [],\n        transition_reference_id: shot.transition_reference_id || '',",
'migrate current shots')

