old_setup = '''            <section className="grid gap-3 md:grid-cols-[1fr_300px]"><input value={title} onChange={(event) => setTitle(event.target.value)} className="border border-white/10 bg-[#17191d] px-4 py-3 text-sm font-bold" placeholder="Scene title" /><div className="grid grid-cols-3 gap-2">{modelAspectRatios.map((ratioId) => { const ratio = RATIOS.find((item) => item.id === ratioId); return <button key={ratioId} type="button" onClick={() => setAspectRatio(ratioId)} className={`border p-2 text-xs font-bold ${aspectRatio === ratioId ? 'border-[#23c7be] bg-[#23c7be]/10 text-[#8ee9e4]' : 'border-white/10 text-white/55'}`}>{ratio?.label || ratioId}<br /><span className="font-black">{ratioId}</span></button>; })}</div></section>'''
new_setup = '''            <section className="border border-white/10 bg-[#17191d] p-4"><div className="grid gap-3 md:grid-cols-[1fr_460px]"><input value={title} onChange={(event) => setTitle(event.target.value)} className="border border-white/10 bg-black/30 px-4 py-3 text-sm font-bold" placeholder="Scene title" /><div className="grid grid-cols-2 gap-2 sm:grid-cols-4">{modelAspectRatios.map((ratioId) => { const ratio = RATIOS.find((item) => item.id === ratioId); return <button key={ratioId} type="button" onClick={() => setAspectRatio(ratioId)} className={`border p-2 text-xs font-bold ${aspectRatio === ratioId ? 'border-[#23c7be] bg-[#23c7be]/10 text-[#8ee9e4]' : 'border-white/10 text-white/55'}`}>{ratio?.label || ratioId}<br /><span className="font-black">{ratioId}</span></button>; })}</div></div><div className="mt-3 grid gap-3 md:grid-cols-3"><label className="text-[10px] font-black uppercase tracking-[0.08em] text-white/55">Model<select value={effectiveModel || ''} onChange={(event) => setSelectedModel(event.target.value || null)} disabled={modelsLoading || !modelOptions.length} className="mt-1 w-full border border-white/10 bg-black/30 p-3 text-sm text-white">{modelsLoading && <option>Loading models…</option>}{modelOptions.map((item) => <option key={item.model_key} value={item.model_key}>{item.name || item.model_key}{item.recommended ? ' — Recommended' : ''}</option>)}</select></label>{resolutionBinding && resolutionOptions.length > 0 && <label className="text-[10px] font-black uppercase tracking-[0.08em] text-white/55">Resolution<select value={String(resolutionValue)} onChange={(event) => updateModelParam(resolutionBinding.name, event.target.value)} className="mt-1 w-full border border-white/10 bg-black/30 p-3 text-sm text-white">{resolutionOptions.map((option) => <option key={option} value={option}>{option}</option>)}</select></label>}{audioBinding && <label className="text-[10px] font-black uppercase tracking-[0.08em] text-white/55">Generate audio<button type="button" onClick={() => updateModelParam(audioBinding.name, !audioValue)} className={`mt-1 w-full border p-3 text-sm font-black ${audioValue ? 'border-[#23c7be] bg-[#23c7be]/10 text-[#8ee9e4]' : 'border-white/10 bg-black/30 text-white/65'}`}>{audioValue ? 'On' : 'Off'}</button></label>}</div></section>'''
